CREATE TABLE IF NOT EXISTS community_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, community_type text NOT NULL, country_code text, jurisdiction_code text, recognition_status text NOT NULL DEFAULT 'Unverified', representative_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_spatial_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, geometry_json jsonb, interest_type text NOT NULL, evidence_status text NOT NULL DEFAULT 'Unverified', visibility text NOT NULL DEFAULT 'Restricted', source_reference text, confidence_score numeric(6,2), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_rights_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, case_type text NOT NULL, status text NOT NULL DEFAULT 'Open', priority text NOT NULL DEFAULT 'High', description text, evidence_reference text, opened_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS community_consent_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, consent_type text NOT NULL, status text NOT NULL DEFAULT 'Pending', process_reference text, decision_date timestamptz, expires_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_benefit_agreements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, agreement_type text NOT NULL, status text NOT NULL DEFAULT 'Proposed', terms_summary text, benefit_schedule jsonb NOT NULL DEFAULT '{}'::jsonb, monitoring_requirements text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_grievances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, grievance_type text NOT NULL, status text NOT NULL DEFAULT 'Open', severity text NOT NULL DEFAULT 'High', summary text, resolution_reference text, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS community_protection_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES community_entities(id) ON DELETE CASCADE, asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, protection_type text NOT NULL, geometry_visibility text NOT NULL DEFAULT 'Restricted', investment_effect text NOT NULL DEFAULT 'Hold', rule_reason text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_community_interests_asset ON community_spatial_interests(asset_id,visibility,evidence_status);
CREATE INDEX IF NOT EXISTS idx_rights_cases_asset ON community_rights_cases(asset_id,status,priority);
CREATE INDEX IF NOT EXISTS idx_consent_asset ON community_consent_records(asset_id,status);
CREATE INDEX IF NOT EXISTS idx_benefit_asset ON community_benefit_agreements(asset_id,status);
CREATE INDEX IF NOT EXISTS idx_grievance_asset ON community_grievances(asset_id,status);
CREATE INDEX IF NOT EXISTS idx_protection_asset ON community_protection_rules(asset_id,active);